// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.diimport timber.log.Timberimport com.roshan.persona.common.AudioDispatcherimport com.roshan.persona.common.CvDispatcherimport com.roshan.persona.common.DefaultDispatcherimport com.roshan.persona.common.IoDispatcherimport com.roshan.persona.common.LlmDispatcherimport com.roshan.persona.common.MainImmediateDispatcherimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.SupervisorJobimport javax.inject.Qualifierimport javax.inject.Singleton/** * Hilt module providing bounded [CoroutineDispatcher]s and the application * coroutine scope. * * Each dispatcher is bound with its own qualifier so features can inject * exactly the one they need. This makes concurrency boundaries explicit * and prevents the "everything goes to Dispatchers.IO" antipattern. */@InstallIn(SingletonComponent::class)@Moduleobject DispatcherModule {    @Provides    @IoDispatcher    fun provideIoDispatcher(): CoroutineDispatcher = Dispatchers.IO    @Provides    @DefaultDispatcher    fun provideDefaultDispatcher(): CoroutineDispatcher = Dispatchers.Default    @Provides    @MainImmediateDispatcher    fun provideMainImmediateDispatcher(): CoroutineDispatcher =        try { Dispatchers.Main.immediate } catch (e: Throwable) { Timber.tag("NOUS.DI").w(e, "Main.immediate not available"); Dispatchers.Main }    @Provides    @LlmDispatcher    fun provideLlmDispatcher(): CoroutineDispatcher = Dispatchers.Default.limitedParallelism(1)    @Provides    @CvDispatcher    fun provideCvDispatcher(): CoroutineDispatcher = Dispatchers.Default.limitedParallelism(2)    @Provides    @AudioDispatcher    fun provideAudioDispatcher(): CoroutineDispatcher = Dispatchers.Default.limitedParallelism(1)}// ─── Application-scoped coroutine scope ─────────────────────────────────────/** Qualifier for the application-scoped coroutine scope. */@Qualifier@Retention(AnnotationRetention.BINARY)annotation class ApplicationScope/** * Application-scoped [CoroutineScope] — uses a [SupervisorJob] so failure of * one child doesn't cancel siblings. Used for crash-recovery work that must * survive activity recreation. * * Inject this when you need to launch work that outlives any UI. */@Module@InstallIn(SingletonComponent::class)object CoroutineScopeModule {    @Provides    @Singleton    @ApplicationScope    fun provideApplicationScope(        @DefaultDispatcher dispatcher: CoroutineDispatcher,    ): CoroutineScope = CoroutineScope(SupervisorJob() + dispatcher)}